<script setup>
import {ref,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useIrrigation} from '../../data/runtime.js'
import {useDraftGuard} from '../../composables/useDraftGuard.js'
import {notify} from '../../composables/feedback.js'
import FormField from '../../components/FormField.vue'
import {clone,stages,requestKey} from './operationUi.js'
const r=useIrrigation(),route=useRoute(),router=useRouter(),draft=ref(null),initial=ref(''),failure=ref(''),errors=ref({}),busy=ref(false),key=requestKey()
const creating=computed(()=>route.path.endsWith('/new')),source=computed(()=>(r.state.entities.Strategy??[]).find(x=>x.strategyId===route.params.id))
watch(()=>[route.params.id,creating.value,r.state.ready],()=>{draft.value=source.value?clone(source.value):creating.value?{farmId:r.state.user?.farmId,name:'',crop:'',stage:'JOINTING',zoneIds:[],triggerMode:'MOISTURE',thresholdVwc:null,targetVolumeM3:null,maxDurationMin:240,allowedStart:'05:30',allowedEnd:'18:20',executionMode:'CONFIRM_REQUIRED',status:'ENABLED'}:null;initial.value=JSON.stringify(draft.value)},{immediate:true})
const guard=useDraftGuard(()=>JSON.stringify(draft.value)!==initial.value),allowed=computed(()=>r.can(creating.value?'STRATEGY_CREATE':'STRATEGY_UPDATE',source.value))
const crops=computed(()=>[...new Set((r.state.entities.CropSeason??[]).map(s=>s.crop))]),zones=computed(()=>(r.state.entities.IrrigationZone??[]).filter(z=>z.status==='ENABLED'&&(r.state.entities.CropSeason??[]).some(s=>s.fieldId===z.fieldId&&s.status==='ENABLED'&&s.crop===draft.value?.crop&&s.stage===draft.value?.stage)))
function back(){router.push(route.query.from?.startsWith('/')?route.query.from:'/strategies')}
function reset(){draft.value=JSON.parse(initial.value);errors.value={};failure.value=''}
async function save(){busy.value=true;failure.value='';errors.value={};try{const payload=clone(draft.value);if(payload.triggerMode!=='MOISTURE')payload.thresholdVwc=null;await r.commit(creating.value?'STRATEGY_CREATE':'STRATEGY_UPDATE',payload,{expectedVersion:draft.value.version,clientRequestId:key(payload)});initial.value=JSON.stringify(draft.value);guard.markClean();notify('策略已保存');back()}catch(e){failure.value=e.message;errors.value=e.fieldErrors??{}}finally{busy.value=false}}
</script>
<template><div v-if="draft" class="page-stack strategy-edit"><div><button class="btn" @click="back">〈　返回</button></div><form @submit.prevent="save"><section class="panel strategy-main"><div class="strategy-left"><FormField label="策略名称" :error="errors.name"><input v-model="draft.name" :readonly="!allowed||busy" required/></FormField><FormField label="适用作物" :error="errors.crop"><select v-model="draft.crop" :disabled="!allowed||busy"><option value="">请选择</option><option v-for="c in crops" :key="c">{{c}}</option></select></FormField><FormField label="适用阶段" :error="errors.stage"><select v-model="draft.stage" :disabled="!allowed||busy"><option v-for="(name,id) in stages" :key="id" :value="id">{{name}}</option></select></FormField><FormField label="适用分区" :error="errors.zoneIds"><div class="zone-checks"><div class="zone-check-list"><label v-for="z in zones" :key="z.zoneId"><input v-model="draft.zoneIds" type="checkbox" :value="z.zoneId" :disabled="!allowed||busy"/> {{z.name}}（{{z.zoneId}}）</label><label v-for="id in draft.zoneIds.filter(id=>!zones.some(z=>z.zoneId===id))" :key="id"><input v-model="draft.zoneIds" type="checkbox" :value="id" :disabled="!allowed||busy"/> {{r.getIndex().byId.IrrigationZone.get(id)?.name||id}}（作物阶段不匹配）</label></div></div></FormField></div><div class="strategy-right"><div class="identity"><FormField label="策略编号"><input :value="draft.strategyId||'保存后自动生成'" readonly/></FormField><FormField label="版本号"><input :value="draft.version??'未创建'" readonly/></FormField><FormField label="状态" :error="errors.status"><select v-model="draft.status" :disabled="!allowed||busy"><option value="ENABLED">启用</option><option value="DISABLED">停用</option></select></FormField></div><FormField label="触发模式" :error="errors.triggerMode"><select v-model="draft.triggerMode" :disabled="!allowed||busy"><option value="MOISTURE">土壤含水量低于阈值</option><option value="SCHEDULE">定时</option><option value="VOLUME">定量</option></select></FormField><FormField v-if="draft.triggerMode==='MOISTURE'" label="土壤含水量阈值（%）" :error="errors.thresholdVwc"><input v-model.number="draft.thresholdVwc" type="number" min="0" max="100" step="0.1" required :readonly="!allowed||busy"/></FormField><FormField label="单次目标灌水量（m³）" :error="errors.targetVolumeM3"><input v-model.number="draft.targetVolumeM3" type="number" min="0.1" step="0.1" required :readonly="!allowed||busy"/></FormField><FormField label="单发最长时长（分钟）" :error="errors.maxDurationMin"><input v-model.number="draft.maxDurationMin" type="number" min="1" required :readonly="!allowed||busy"/></FormField></div></section><section class="panel execution"><div><label>允许执行时段</label><div class="time-range"><input v-model="draft.allowedStart" type="time" :readonly="!allowed||busy"/><span>至</span><input v-model="draft.allowedEnd" type="time" :readonly="!allowed||busy"/></div><p class="error-text">{{errors.allowedStart||errors.allowedEnd}}</p></div><div class="execution-mode"><FormField label="人工确认执行方式"><select v-model="draft.executionMode" disabled><option value="CONFIRM_REQUIRED">人工确认</option></select></FormField><div class="auto-row"><span>自动执行</span><input type="checkbox" disabled aria-label="自动执行" aria-describedby="auto-execution-unavailable"/><span class="muted" title="尚未连接真实设备反馈、本地保护与现场联动签核">未开启</span></div><small id="auto-execution-unavailable" class="muted visually-hidden">尚未具备设备反馈、本地保护及现场联动签核，自动执行不可用</small></div></section><p v-if="source&amp;&amp;draft.version!==source.version" class="error-text" role="status">来源版本已更新，当前输入已保留；保存时将检查版本冲突。</p><p v-if="failure" class="error-text" role="alert">{{failure}}</p><div class="form-actions"><button class="btn btn-primary" :disabled="busy||!allowed">{{busy?'保存中…':'保存'}}</button><button class="btn" type="button" :disabled="busy" @click="reset">重置</button><button class="btn" type="button" :disabled="busy" @click="back">取消</button></div></form></div><div v-else class="panel empty-state">{{r.state.ready?'策略不存在或无权访问':'加载中…'}} <button class="btn" @click="back">返回</button></div></template>
<style scoped>.strategy-edit form{display:grid;gap:24px}.strategy-main{display:grid;grid-template-columns:1fr 1.16fr;padding:26px;gap:25px;min-height:476px}.strategy-left{display:grid;gap:20px;align-content:start}.strategy-right{border-left:1px solid #e1e8e4;padding-left:25px;display:grid;gap:26px;align-content:start}.identity{display:grid;grid-template-columns:2fr .62fr .92fr;gap:20px}.strategy-right>:not(.identity){display:grid;grid-template-columns:170px 1fr;align-items:center}.zone-checks{padding:12px 16px;background:#f6f9f9;border:1px solid #e1e8e4;border-radius:7px;height:100px;max-height:100px;overflow:hidden}.zone-check-list{height:66px;max-height:66px;overflow:auto;display:grid;align-content:start;gap:12px;scrollbar-width:thin}.zone-checks input{width:21px;height:21px;vertical-align:middle;accent-color:#16765b}.execution{display:grid;grid-template-columns:.95fr 1.05fr;padding:26px;gap:38px;min-height:170px}.execution-mode{border-left:1px solid #e1e8e4;padding-left:38px}.execution-mode :deep(.form-field){display:grid;grid-template-columns:170px 1fr;align-items:center}.time-range{display:flex;gap:32px;align-items:center;margin-top:12px}.time-range input{width:42%}.auto-row{display:flex;align-items:center;gap:24px;margin:16px 0 6px}.auto-row input{appearance:none;position:relative;width:48px;height:26px;min-height:26px;padding:0;border:0;border-radius:999px;background:#d6ddde;cursor:not-allowed;opacity:1}.auto-row input::before{content:"";position:absolute;left:3px;top:3px;width:20px;height:20px;border-radius:50%;background:white;box-shadow:0 1px 2px #627b7a55}.auto-row input:disabled{opacity:1}.visually-hidden{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}.form-actions{margin-top:16px}.form-actions .btn{min-width:124px}@media(max-width:1000px){.strategy-main,.execution{grid-template-columns:1fr}.strategy-right,.execution-mode{border:0;padding-left:0}}</style>
